import telnetlib
import re
import logging
import time
from ta_attenuator.attenuator import Attenuator
from ta_attenuator.attenuator import ChangingAttenutionValueOfNotReservedPort
from ta_attenuator.attenuator import AttenuationValueIsOtherThanExpected


class HytemAttenuator(Attenuator):
    """Implementation of Hytem attenuator"""
    # pylint: disable=anomalous-backslash-in-string, consider-iterating-dictionary, bare-except, unidiomatic-typecheck, unused-variable
    STARTING_PORT = 10001

    def __init__(self, min_attenuation, max_attenuation, ip):
        super(HytemAttenuator, self).__init__()
        self.ip = ip
        self.conns = {}
        self.max_attenuation = max_attenuation
        self.min_attenuation = min_attenuation

    def connect_attenuator_controller(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-path of that device

        Hytem handles 4 RF-paths at 4 predefined ports: 10001, 10002, 10003, 10004
        """
        if 'rf_paths_at_attenuator' in kwargs:
            rf_paths = kwargs['rf_paths_at_attenuator']
            for port_id in rf_paths:
                conn = telnetlib.Telnet(self.ip, self.STARTING_PORT + port_id)
                self.conns[port_id] = conn
        else:
            for port_id in range(0, 4):
                conn = telnetlib.Telnet(self.ip, self.STARTING_PORT + port_id)
                self.conns[port_id] = conn

    def read_rf_paths_attenuation(self, rf_paths):
        """read attenuation value in db for the first rf_path"""
        raise NotImplementedError

    def _refresh_attenuator_port(self, port_id):
        """
        Refresh connection with attenuation controller for a specific port_id
        :param port_id: attenuator's port id (integer value in {0,1,2,3})
        :return: None
        """
        conn = self.conns.pop(port_id)
        conn.close()
        del conn
        # mandatory to wait
        time.sleep(1)
        conn = telnetlib.Telnet(self.ip, self.STARTING_PORT + port_id)
        self.conns[port_id] = conn

    def disconnect_attenuator_controller(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        if 'rf_paths_at_attenuator' in kwargs:
            rf_paths = kwargs['rf_paths_at_attenuator']
            for rf_path in rf_paths:
                conn = self.conns.pop(rf_path)
                conn.close()
        else:
            for connection in self.conns.keys():
                self.conns[connection].close()
            self.conns.clear()

    def _set_single_rf_path_decibel_attenuation(self, rf_path_address, attenuation_value_db, confirm=True):
        """
        Set attenuation with command of following syntax:
        ATT x yyy
        Sets the attuenation value of port x in 0.1dB
        x number of port (0 for TCP 10001, 1 for TCP 10002 ...)
        yyy attenuation in 0.1dB, no comma allowed, should always be written over 3 digits (e.g. 010 instead of 10)
            :param rf_path_address: 0..3
            :param attenuation_value_db: float or int in dB
            :return: None
        """
        if not self.check_if_port_is_reserved(rf_path_address):
            raise ChangingAttenutionValueOfNotReservedPort("Port {} was not reserved on attenuator!"
                                                           "Please check if this RF path "
                                                           "belongs to your cell.".format(rf_path_address))
        self._refresh_attenuator_port(rf_path_address)

        attenuation_value_db = self._provide_correct_att_format(attenuation_value_db)
        cmd = "ATT {} {}".format(rf_path_address, attenuation_value_db)
        check_att = self._check_single_rf_path_attenuation(rf_path_address, attenuation_value_db)
        attempt = 5
        while attempt and not check_att:
            self._write(cmd, rf_path_address)
            check_att = self._check_single_rf_path_attenuation(rf_path_address, attenuation_value_db)
            attempt -= 1
        if attempt == 0 and not check_att:
            raise AttenuationValueIsOtherThanExpected("Expected value {} "
                                                      "was not set on RF path {}.".format(attenuation_value_db,
                                                                                          rf_path_address))

    def _write(self, cmd, port_id, refresh=True):
        if refresh:
            self._refresh_attenuator_port(port_id)
        conn = self.conns[port_id]
        try:
            conn.write(cmd + '\n')
            time.sleep(2)  # mandatory to wait
        except IOError as e:
            logging.warning("Write cmd failed with error : {}".format(e))

    def _check_single_rf_path_attenuation(self, port_id, value):
        """
        Read attenuation value at port_id
        :param port_id: attenuator's port id (integer value in {0,1,2,3})
        :return: attenuation value (type : str)
        """
        for i in range(6):  # mandatory 3 times
            self._write('STA?', port_id, refresh=False)
            output = self._read(port_id)
            if output:
                read_val = output.split()[-1]
                if read_val not in ('?', '', None, '\n', '\t', '\s'):
                    try:
                        return int(read_val) == int(value)
                    except:
                        pass
        return False

    def _read(self, port_id):
        conn = self.conns[port_id]
        try:
            output = conn.read_very_eager()
            return output
        except IOError as e:
            logging.warning("Read very eager failed with error : {}".format(e))

    def _provide_correct_att_format(self, att_value):
        """Converts given numeric value to a three digit string, where last digit is a decimal part.
        Throws exception if decimal part length exceeds one digit or whole number length exceeds three digits.
        If whole number length is below three digits, value is topped up with zeros added on the left side.
        Example:
              0.01  -> 001
                 1  -> 010
                10  -> 100
        :param att_value - integer or float with one decimal place
        :return: attenuation value in a format suitable for Hytem attenuator (str) """
        att_string = ""
        if type(att_value) == float:
            att_string = str(att_value)
            regex_determine_decimal_part_length = re.compile(r'(\d+\.\d)(\d*)')
            match = re.match(regex_determine_decimal_part_length, att_string)
            if match.group(2):
                raise ValueError('Decimal part too long in provided value {}.'
                                 ' Only one decimal place is allowed'.format(att_value))
            att_string = match.group(1)
            regex_find_dot = re.compile(r'\.')
            att_string = re.sub(regex_find_dot, '', att_string)
        elif type(att_value) == int:
            att_value *= 10
            att_string = str(att_value)
        else:
            raise TypeError("Wrong type of value provided: {}.".format(type(att_value)))
        att_string = self._ensure_attenuation_value_string_has_correct_length(att_string)
        return att_string

    def _ensure_attenuation_value_string_has_correct_length(self, att_string):
        """ Fits given string to three characters format.
        Examples:
            1    -> 001
            11   -> 011
            111  -> 111
            1111 -> Throws exception
        :param att_string - attenuation value in string format
        :return: attenuation value in a three-digits format (str) """
        if len(att_string) > 3:
            raise ValueError("Expected value 1 to 3 characters long, but got {}"
                             "(last digit is decimal part)".format(att_string))
        else:
            while len(att_string) < 3:
                att_string = '0' + att_string
        return att_string

    def get_max_decibel_attenuation(self):
        """
        Returns Maximal value of attenuation possible on this attenuator. For ex. 95 dB
        :return: float
        """
        return self.max_attenuation

    def get_min_decibel_attenuation(self):
        """
        Returns Minimal value of attenuation possible on this attenuator. For ex. 5 dB
        :return: float
        """
        return self.min_attenuation
